INVALID = [['x', 0, 0], ['x', 5, 5], ['x', 5, -1], ['x', -3, 0]]


class TextChunkingTest(unittest.TestCase):
    def test_cases(self):
        for text, max_chars, overlap, expected in CASES:
            got = chunk_text(text, max_chars, overlap)
            self.assertEqual(got, expected, (text, max_chars, overlap))
            self.assertTrue(all(0 < len(c) <= max_chars for c in got))

    def test_invalid(self):
        for text, max_chars, overlap in INVALID:
            with self.assertRaises(ValueError):
                chunk_text(text, max_chars, overlap)

    def test_code_points(self):
        self.assertEqual(chunk_text("\U0001F600" * 5, 2), ["\U0001F600" * 2, "\U0001F600" * 2, "\U0001F600"])


if __name__ == "__main__":
    unittest.main()
